      authority: reference.authority,
      path: removeDotSegments(reference.path),
      query: reference.query,
      fragment: reference.fragment,
    }
  }
  if (reference.authority !== undefined) {
    return {
      scheme: base.scheme,
      authority: reference.authority,
      path: removeDotSegments(reference.path),
      query: reference.query,
      fragment: reference.fragment,
    }
  }
  if (reference.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: reference.query === undefined ? base.query : reference.query,
      fragment: reference.fragment,
    }
  }
  const path = reference.path.startsWith('/')
    ? removeDotSegments(reference.path)
    : removeDotSegments(merge(base, reference.path))
  return {
    scheme: base.scheme,
    authority: base.authority,
    path,
    query: reference.query,
    fragment: reference.fragment,
  }
